"""Standalone before/after report. All values come from saved paired runs."""
import json
from build_evaluation_report import STYLE


def render(summary, matches, analyses, corrections, events, old, *, shared=None, shared_agent=None):
    payload = json.dumps({'summary': summary, 'matches': matches, 'analyses': analyses,
        'corrections': corrections, 'events': [event.model_dump() for event in events],
        'old_queries': old['retrieval'], 'old_reviews': old['reviews'],
        'companies': old['companies'], 'shared': shared, 'shared_agent': shared_agent}, ensure_ascii=False).replace('<', '\\u003c').replace('>', '\\u003e').replace('&', '\\u0026')
    script = r'''
const D=JSON.parse(document.getElementById('data').textContent),S=D.summary;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const events=Object.fromEntries(D.events.map(e=>[e.id,e])),companies=Object.fromEntries(D.companies.map(c=>[c.company_id,c]));
const labels={direct:'Прямая',indirect:'Косвенная',weak:'Слабая',unrelated:'Не подтверждена',not_reviewed:'Не проверено'};
const refs=new Map(D.old_reviews.filter(x=>x.result).map(x=>[x.company_id+'|'+x.news_id,x.result]));
const link=e=>`<a href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">${esc(e.title)}</a>`;
const badge=x=>`<span class="badge ${esc(x)}">${esc(labels[x]||x)}</span>`;
const stats=[['Классификация с валидными ссылками',`${S.classification_before.success} → ${S.classification_after.success}`],['Компании с поддержанным ОКВЭД',`${S.okved_covered_before} → ${S.okved_covered_after}`],['Найдено из 4 прежних положительных пар',`${S.found_before_top5} → ${S.found_after_top5}`],['Повторные разборы',`${S.analyses_success} / ${S.analyses_planned}`],['Новый прогон по usage.cost',`$${S.reported_cost_usd.toFixed(2)}`]];
document.getElementById('stats').innerHTML=stats.map(([name,value])=>`<div class="stat"><strong>${value}</strong><span>${name}</span></div>`).join('');
document.getElementById('reliability').innerHTML=`<p>После изменений: ${S.model_attempts} попыток. ${S.classification_after.failed} незавершённых классификаций. Стоимость относится только к ответам с usage, стоимость сетевых сбоев неизвестна.</p><pre style="white-space:pre-wrap">${esc(JSON.stringify(S.statuses,null,2))}</pre>`;
document.getElementById('limits').innerHTML=S.limitations.map(x=>`<li>${esc(x)}</li>`).join('');
const select=document.getElementById('company');select.innerHTML=D.companies.map(c=>`<option value="${esc(c.company_id)}">${esc(c.company_id)} · ${esc(c.code)} · ${esc(c.region)}</option>`).join('');
function draw(){const id=select.value,co=companies[id];document.getElementById('industry').textContent=co.industry;const before=D.old_queries.find(x=>x.company_id===id&&x.variant==='profile').hits.slice(0,5),after=D.matches.find(x=>x.company_id===id).candidates.slice(0,5);document.getElementById('results').innerHTML=[['До: широкий запрос к E5',before],['После: отраслевые запросы + ключевые слова + E5',after]].map(([title,rows])=>`<div class="panel"><h3>${title}</h3><table><thead><tr><th>Кандидат</th><th>Прежняя оценка связи</th></tr></thead><tbody>`+rows.map(row=>{const review=refs.get(id+'|'+row.id);const reasons=row.match_reasons?.map(x=>x.kind==='industry'?'Вид деятельности':x.kind==='financing'?'Ключевая ставка / банковские услуги':`Отрасль контрагента ${x.okved} · ${x.turnover_share_pct}% оборота`).join('; ');return `<tr><td>${link(events[row.id])}${reasons?`<p class="note">${esc(reasons)}</p>`:''}</td><td>${badge(review?.relevance||'not_reviewed')}</td></tr>`}).join('')+`</tbody></table>${rows.length?'':'<p class="note">Кандидатов с достаточным лексическим основанием в этом снимке нет.</p>'}</div>`).join('');const plan=D.matches.find(x=>x.company_id===id).search_plan;document.getElementById('plan').textContent=JSON.stringify(plan,null,2)}select.onchange=draw;draw();
const known=D.corrections.find(x=>x.before.includes('годовые поступления от депозитов'));document.getElementById('summary-fix').innerHTML=known?`<h3>Контроль на неизменённых claims: ${esc(known.company_id)}</h3><p class="note">Здесь изменён только способ построения summary; утверждения взяты из прежнего сохранённого ответа.</p><div class="grid"><div><b>До</b><blockquote>${esc(known.before)}</blockquote></div><div><b>После</b><blockquote>${esc(known.after)}</blockquote></div></div>`:'';
if(D.shared){const x=D.shared,c=x.counts;document.getElementById('shared').innerHTML=`<p>Проверено отдельно после импорта компаний: <b>${c.companies} профилей и ${c.company_vectors} векторов</b>. Сохранены ${c.news} новостей и ${c.news_vectors} их векторов. Права роли агента — только чтение; проверки среза времени пройдены.</p><p class="note">Одна локальная E5, 384 измерения, разные правила подготовки новостей и компаний. Новость кодируется как query для поиска по passage профилей. Ниже — кандидаты, без оценки влияния.</p>`+x.reverse_matches.map(r=>`<details class="panel case"><summary>${esc(r.title)}</summary><table><thead><tr><th>Компания</th><th>ОКВЭД</th><th>Косинусное сходство</th></tr></thead><tbody>`+r.candidates.map(c=>`<tr><td>${esc(c.id)}</td><td>${esc(c.okved_code)} · ${esc(c.okved_name)}</td><td>${c.similarity.toFixed(3)}</td></tr>`).join('')+'</tbody></table></details>').join('')+(D.shared_agent?`<p><b>Полный запуск через общую БД:</b> ${esc(D.shared_agent.company_id)}, статус ${esc(D.shared_agent.result.status)}. ${esc(D.shared_agent.result.summary)}</p><p class="note">Цитаты повторно проверены. Источники и вызовы инструментов сохранены в shared-agent-check.json. Этот контроль использует новый as_of и не включён в показатели парного сравнения выше.</p>`:'');}else{document.getElementById('shared').textContent='Отдельная проверка общей БД не приложена.';}
if(D.shared){document.querySelectorAll('#shared .case').forEach((el,i)=>{const r=D.shared.reverse_matches[i];if(r.reranked)el.insertAdjacentHTML('beforeend',`<h3>После учёта темы новости и ОКВЭД</h3><p class="note">Темы: ${esc(r.reranked.topics_used.join(', '))}. Сначала совпадение отрасли, затем исходное сходство E5. Это ранжирование кандидатов.</p><table><thead><tr><th>Компания</th><th>ОКВЭД</th><th>Сходство E5</th><th>Совпавшие темы</th></tr></thead><tbody>`+r.reranked.candidates.map(c=>`<tr><td>${esc(c.id)}</td><td>${esc(c.okved_code)}</td><td>${c.similarity.toFixed(3)}</td><td>${esc(c.matched_topics.join(', ')||'—')}</td></tr>`).join('')+'</tbody></table>')});if(D.shared_agent?.run_usage)document.getElementById('shared').insertAdjacentHTML('beforeend',`<p class="note">Отдельный запуск агента: ${D.shared_agent.run_usage.attempts} попыток, $${D.shared_agent.run_usage.reported_cost_usd.toFixed(2)} по usage.cost; в $${S.reported_cost_usd.toFixed(2)} парного сравнения не входит.</p>`);}
document.getElementById('cases').innerHTML=D.analyses.filter(r=>r.result).map(r=>{const state=r.result,x=state.result;return `<details class="panel case"><summary>${esc(r.company_id)} · ${esc(events[r.news_id].title)}</summary><p>${esc(x.summary)}</p><p class="note">Статус ${esc(x.status)}; источников контекста ${state.retrieved_sources.length}; вызовов инструментов ${state.trace.length}. Каждый факт и гипотеза имеют цитаты, но это не доказательство истинности вывода.</p>`+x.claims.map(cl=>`<div class="claim"><span class="pill">${cl.kind==='fact'?'Факт источника':'Гипотеза'}</span>${esc(cl.text)}<details><summary>Цитаты</summary>`+cl.evidence.map(e=>`<blockquote><span class="source">${esc(e.source_id)}</span>${esc(e.quote)}</blockquote>`).join('')+'</details></div>').join('')+'<h3>Недостающие данные</h3><ul>'+x.missing_data.map(t=>`<li>${esc(t)}</li>`).join('')+'</ul></details>'}).join('');
'''
    return '''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Улучшение пайплайна — сравнение</title><style>''' + STYLE + '''</style><main><header><div class="eyebrow">Сравнение на одном снимке · 22 октября 2026</div><h1>От совпадения слов<br>к проверяемой связи</h1><p class="intro">Повторная проверка на 153 новостях и 12 компаниях. Старый прогон сохранён, срез времени и исходные данные одинаковы.</p><div class="stats" id="stats"></div></header>
<div class="alert"><b>Это сравнение поведения пайплайна, а не измеренная точность продукта.</b><br>Проверяем возвращение ранее найденных связей, устойчивость формата и известную ошибку summary. Новые кандидаты без прежней оценки явно помечены.</div>
<section class="grid"><div class="panel"><h2>Поиск и сопоставление</h2><ul class="checks"><li>ОКВЭД 45, 46 и 68 добавлены; для торговли бытовой техникой учтён точный код 46.43.</li><li>Короткий отраслевой запрос вместо полного юридического описания и региона регистрации.</li><li>Ключевые слова + E5, объединение по рангам; семантического сходства одного недостаточно.</li><li>Отдельные ветки для ключевой ставки и отраслей контрагентов, с сохранением ограничений.</li><li>Устранение близких повторов и защита от военного «логистического центра».</li></ul></div><div class="panel"><h2>Цитирование и надёжность</h2><ul class="checks"><li>Модель выбирает fragment_id; точный текст цитаты подставляет код.</li><li>Неизвестные ID и изменённые цитаты отклоняются.</li><li>Summary повторяет принятые claims и не добавляет свободно сгенерированных сведений.</li><li>Ограниченные повторы временных сетевых ошибок; ошибки авторизации не повторяются.</li><li>Недоступный источник не запрашивается повторно в том же исследовании.</li></ul></div></section>
<section><h2>Выдача до и после</h2><p class="note">Колонки используют прежние замороженные оценки 64 пар. Новые кандидаты не получают положительную метку автоматически. Candidate score — правило сортировки, не вероятность и не важность.</p><div class="toolbar"><select id="company" aria-label="Компания"></select></div><h3 id="industry"></h3><div class="grid" id="results"></div><details class="panel case"><summary>Почему сформированы такие запросы</summary><pre id="plan" style="white-space:pre-wrap;overflow-wrap:anywhere"></pre></details></section>
<section><h2>Проверка найденной смысловой ошибки</h2><div class="panel" id="summary-fix"></div><p class="note">Гарантия касается состава summary. Логическое следование каждого claim из его цитат по-прежнему требует отдельной проверки.</p></section>
<section><h2>Общий модуль компаний и эмбеддинги</h2><div class="panel" id="shared"></div></section><section><h2>Повторные исследования агентом</h2><div id="cases"></div></section><section class="grid"><div class="panel"><h2>Надёжность и расход</h2><div id="reliability"></div></div><div class="panel"><h2>Границы результата</h2><ul id="limits"></ul></div></section><footer>Полные результаты: comparison.json. Параметры и выводы: findings.md. Базовый отчёт сохранён отдельно. Банковские документы в этот прогон не входили.</footer><script id="data" type="application/json">''' + payload + '''</script><script>''' + script + '''</script></main></html>'''
